pub enum QueueFaultReason { InputOverflow, TextInputStateMissing, InvalidTextRange, AllocationFailure }

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct QueueFault { pub reason: QueueFaultReason, pub coalesced_or_dropped: u64 }

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum WindowError { ExpiredOwner, ExpiredWindow, InvalidConfig, InvalidTextInputState, QueueFault, Native(NativeFault) }

#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Point { pub x: f64, pub y: f64 }
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Size { pub width: f64, pub height: f64 }
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Rect { pub origin: Point, pub size: Size }
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct SizeU32 { pub width: u32, pub height: u32 }

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Cursor { Arrow, OpenHand, ClosedHand, ResizeNorthSouth, ResizeEastWest, ResizeNorthwestSoutheast, ResizeNortheastSouthwest, Rotate }
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Modifiers(pub u32);
impl Modifiers {
    pub const SHIFT: u32 = 1;
    pub const COMMAND: u32 = 2;
    pub const OPTION: u32 = 4;
    pub const CONTROL: u32 = 8;
    pub const fn from_native_bits(bits: u64) -> Self {
        let mut out = 0;
        if bits & (1 << 17) != 0 { out |= Self::SHIFT; }
        if bits & (1 << 20) != 0 { out |= Self::COMMAND; }
        if bits & (1 << 19) != 0 { out |= Self::OPTION; }
        if bits & (1 << 18) != 0 { out |= Self::CONTROL; }
        Self(out)
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct PointerEvent { pub at: Point, pub button: Option<u8>, pub click_count: u8, pub modifiers: Modifiers, pub timestamp_seconds: f64 }
#[derive(Clone, Debug, PartialEq)]
