#[derive(Clone, Debug, PartialEq)]
pub struct TextInputState { pub source_window: WindowId, pub text: String, pub selection_utf8: Range<usize>, pub marked_utf8: Option<Range<usize>>, pub marked_attributes: Vec<TextAttributeSpan>, pub candidate_rect_points: Rect }

#[derive(Clone, Debug, PartialEq)]
pub enum WindowEvent {
    Open, Focus(bool), AppearanceChanged { dark: bool }, Resize { points: Size, pixels: SizeU32 }, BackingScaleChanged { scale: f64, pixels: SizeU32 },
    KeyDown { code: u16, modifiers: Modifiers }, KeyUp { code: u16, modifiers: Modifiers }, Pointer(PointerEvent), Scroll(ScrollEvent), Magnify { at: Point, amount: f64 },
    TextCommitted(String), Composition(Composition), InputReset { sequence: u64, all_keys_up: bool, all_buttons_up: bool }, CloseRequested,
    AnimationTick { monotonic_seconds: f64 }, QueueFault(QueueFault),
}
#[derive(Clone, Debug, PartialEq)]
pub struct EventBatch { pub events: Vec<WindowEvent>, pub pending: bool }
impl EventBatch { pub(crate) fn empty() -> Self { Self { events: Vec::new(), pending: false } } }
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct WindowConfig { pub title: String, pub width_points: u32, pub height_points: u32, pub resizable: bool, pub initially_hidden: bool }
impl WindowConfig {
    pub(crate) fn valid(&self) -> bool { !self.title.is_empty() && self.title.len() <= 1024 && !self.title.contains('\0') && (1..=4096).contains(&self.width_points) && (1..=4096).contains(&self.height_points) }
}
pub(crate) fn validate_text_state(id: WindowId, state: &TextInputState) -> bool {
    fn range_ok(text: &str, range: &Range<usize>) -> bool { range.start <= range.end && range.end <= text.len() && text.is_char_boundary(range.start) && text.is_char_boundary(range.end) }
    state.source_window == id && state.text.len() <= 64 * 1024 && range_ok(&state.text, &state.selection_utf8)
        && state.marked_utf8.as_ref().is_none_or(|r| range_ok(&state.text, r))
        && state.marked_attributes.len() <= 256 && state.marked_attributes.iter().all(|a| range_ok(&state.text, &a.range_utf8))
        && state.candidate_rect_points.origin.x.is_finite() && state.candidate_rect_points.origin.y.is_finite()
        && state.candidate_rect_points.size.width.is_finite() && state.candidate_rect_points.size.height.is_finite()
        && state.candidate_rect_points.size.width >= 0.0 && state.candidate_rect_points.size.height >= 0.0
}
