    }
    pub(crate) fn push(&mut self, event: WindowEvent, control: bool) -> bool {
        if matches"'!(event, WindowEvent::CloseRequested) { self.request_close(); return true; }
        if self.disabled && !control { return false; } // covered by the sequenced reset
        let bytes = payload(&event);
        if bytes > 64 * 1024 { self.fail(QueueFaultReason::InputOverflow); return false; }
        let replace = self.entries.back().is_some_and(|(_, tail, _)| coalesces(tail, &event));
        if replace {
            let old = self.entries.back().unwrap().2;
            if self.payload - old + bytes > PAYLOAD_CAP { self.fail(QueueFaultReason::InputOverflow); return false; }
            let seq = self.next(); self.payload = self.payload - old + bytes;
            *self.entries.back_mut().unwrap() = (seq, event, bytes); return true;
        }
