//"'! Main-thread callback state. Native delegates retain only Weak<RouteState>.
use std::cell::{Cell, RefCell};
use std::rc::{Rc, Weak};
use std::time::Instant;
use objc2::rc::{Retained, Weak as NativeWeak};
use objc2_app_kit::{NSView, NSWindow};
use crate::{guard_native_call, NativeFault};
use super::{queue::EventQueue, types::*};

pub(crate) struct RouteState {
    pub id: WindowId, pub active: Cell<bool>, pub focused: Cell<bool>,
    pub queue: RefCell<EventQueue>, pub text: RefCell<Option<TextInputState>>,
    pub composition: RefCell<Option<Composition>>, pub native_fault: Cell<Option<NativeFault>>,
    native: RefCell<Option<(NativeWeak<NSWindow>, NativeWeak<NSView>)>>,
    pub tick_generation: Cell<u64>, clock: Instant, last_timestamp: Cell<f64>,
}
impl RouteState {
    pub fn new(id: WindowId) -> Rc<Self> { Rc::new(Self { id, active:Cell::new(true), focused:Cell::new(false), queue:RefCell::new(EventQueue::default()), text:RefCell::new(None), composition:RefCell::new(None), native_fault:Cell::new(None), native:RefCell::new(None), tick_generation:Cell::new(0), clock:Instant::now(), last_timestamp:Cell::new(0.0) }) }
    pub fn bind(&self, window:&Retained<NSWindow>, view:&Retained<NSView>) {
        let weak = (NativeWeak::from_retained(window), NativeWeak::from_retained(view));
        *self.native.borrow_mut()=Some(weak);
    }
    pub fn native(&self)->Option<(Retained<NSWindow>,Retained<NSView>)> {
        if !self.active.get() { return None; }
        // objc2'"'s weak load/clone performs runtime retain bookkeeping, not a
        // message send. Retain/release exceptions are outside our unwind fence.
        let pair=self.native.borrow().as_ref().map(|(w,v)|(w.clone(),v.clone()))?;
        Some((pair.0.load()?,pair.1.load()?))
    }
    pub fn timestamp(&self, value:f64)->Option<f64> {
        if "'!value.is_finite() || value<0.0 || value>1.0e12 { self.fail(QueueFaultReason::InputOverflow); return None; }
        let value=value.max(self.last_timestamp.get()); self.last_timestamp.set(value); Some(value)
    }
    pub fn seconds(&self)->f64 { self.clock.elapsed().as_secs_f64() }
    pub fn emit(&self,event:WindowEvent,control:bool) {
        if !self.active.get() { return; }
        // Enqueue failure is represented by fault/reset latches, or by a reset
        // already disabling ingress. The callback never discards an unreported loss.
        self.queue.borrow_mut().push(event,control);
        super::ticks::wake();
    }
    pub fn fault(&self, reason:QueueFaultReason) { if self.active.get() { self.queue.borrow_mut().fault(reason); super::ticks::wake(); } }
    pub fn fail(&self, reason:QueueFaultReason) { if self.active.get() { self.queue.borrow_mut().fail(reason); super::ticks::wake(); } }
    pub fn snapshot(&self)->Option<TextInputState> {
        if !self.active.get() { return None; }
        let snapshot=self.text.borrow().clone();
        if snapshot.as_ref().is_none_or(|s| s.source_window!=self.id) { self.fault(QueueFaultReason::TextInputStateMissing); None } else { snapshot }
    }
    pub fn invalidate(&self) {
        self.active.set(false); self.tick_generation.set(self.tick_generation.get().saturating_add(1));
        self.focused.set(false); self.text.borrow_mut().take(); self.composition.borrow_mut().take();
        self.queue.borrow_mut().clear(); self.native.borrow_mut().take();
    }
