    let accepted=q.drain(256,false);assert!(accepted.pending);assert_eq!(accepted.events.iter().filter(|e|matches!(e,WindowEvent::KeyUp{..})).count(),16);
    let sticky=q.drain(3,false);assert!(matches!(sticky.events[0],WindowEvent::QueueFault(_)));
    let sequence=match sticky.events[1]{WindowEvent::InputReset{sequence,..}=>sequence,_=>panic!("reset missing")};
    assert!(matches!(sticky.events[2],WindowEvent::CloseRequested));assert!(!sticky.pending);
    assert!(!q.acknowledge_reset(sequence.wrapping_sub(1)));assert!(!q.push(key(false),false));
    assert!(q.push(WindowEvent::Focus(false),true));assert!(q.acknowledge_reset(sequence));assert!(!q.acknowledge_reset(sequence));assert!(q.push(key(false),false));
}

